document.addEventListener('click',e=>{
 const button=e.target.closest('[data-service-v06]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(!state)return;
 const action=button.dataset.serviceV06,index=Number(button.dataset.serviceIndex),id=button.dataset.serviceId;
 if(action==='services')showServicesV06();else if(action==='missions')showServiceMissionsV06();else if(action==='open')showServiceV06(index);else if(action==='build')buildServiceV06(button.dataset.serviceType);else if(action==='upgrade')upgradeServiceV06(index);else if(action==='donate')donateCollectibleV06(id);else if(action==='meeting')holdParkMeetingV06(index);else if(action==='garden')completeServiceGardenV06(index);else if(action==='research')researchServiceV06(id);else if(action==='labcraft')craftLabRecipeV06(id);else if(action==='pizza')cookPizzaV06(index,id);else if(action==='share')sharePizzaV06(index);else if(action==='errand')completeLibraryErrandV06(index);else if(action==='lesson')learnServiceRecipeV06(index,id);else if(action==='seed')buyGreenhouseSeedV06(index,id);else if(action==='seedexchange')exchangeServiceSeedV06(index);else if(action==='shop')showServiceShopV06();else if(action==='legacyshop')showShop();else if(action==='buy')buyServiceStockV06(id);else if(action==='farm')showFarm();else if(action==='collections'&&typeof showCollectionsV06==='function')showCollectionsV06();else if(action==='journal'&&typeof showBiomeGuideV06==='function')showBiomeGuideV06();else if(action==='close')hideModal();
},true);
